#!/bin/sh
# Generated by FWShift: a Google Cloud network firewall policy, created with gcloud. Read the report first: what is
# not written is listed there.
#
#   DRY_RUN=1 sh THIS_FILE                              prints the commands; needs no access to Google Cloud
#   GCLOUD_OPTS='--project my-project' sh THIS_FILE     creates the policy and its rules
#
# The policy is associated with no network: nothing changes for any traffic until you associate it:
#   gcloud compute network-firewall-policies associations create --firewall-policy fwshift --network NETWORK --global-firewall-policy
# It decides every connection of that network. Set the network's enforcement order to BEFORE_CLASSIC_FIREWALL, or
# the VPC firewall rules of the network decide first. A policy of the same name stops the script before anything is
# created; a command gcloud refuses stops it where it is (delete the policy and run it again).
set -u
DRY_RUN="${DRY_RUN:-}"
GCLOUD_OPTS="${GCLOUD_OPTS:-}"
POLICY=fwshift
fail() { printf 'FAILED: %s\n' "$*" >&2; exit 1; }
run() {
  if [ -n "$DRY_RUN" ]; then printf 'gcloud' >&2; printf ' %s' "$@" >&2; printf '\n' >&2; return 0; fi
  gcloud "$@" $GCLOUD_OPTS --quiet >/dev/null || fail "gcloud $1 $2 $3 $4"
}
if [ -z "$DRY_RUN" ] && gcloud compute network-firewall-policies describe "$POLICY" --global $GCLOUD_OPTS >/dev/null 2>&1; then
  fail "a network firewall policy named $POLICY exists already; nothing was created"
fi

run compute network-firewall-policies create "$POLICY" --global '--description=Generated by FWShift; review the conversion report before associating it'

run compute network-firewall-policies rules create 1000 --firewall-policy="$POLICY" --global-firewall-policy --direction=INGRESS --action=allow --src-ip-ranges=10.10.0.0/16 --dest-ip-ranges=192.0.2.53/32 --layer4-configs=tcp:53,udp:53 '--description=DNS to resolvers'
run compute network-firewall-policies rules create 1010 --firewall-policy="$POLICY" --global-firewall-policy --direction=EGRESS --action=allow --src-ip-ranges=10.10.0.0/16 --dest-ip-ranges=192.0.2.53/32 --layer4-configs=tcp:53,udp:53 '--description=DNS to resolvers'
run compute network-firewall-policies rules create 1020 --firewall-policy="$POLICY" --global-firewall-policy --direction=INGRESS --action=allow --src-ip-ranges=0.0.0.0/0 --dest-ip-ranges=192.0.2.123/32 --layer4-configs=udp:123 --description=NTP
run compute network-firewall-policies rules create 1030 --firewall-policy="$POLICY" --global-firewall-policy --direction=EGRESS --action=allow --src-ip-ranges=0.0.0.0/0 --dest-ip-ranges=192.0.2.123/32 --layer4-configs=udp:123 --description=NTP
run compute network-firewall-policies rules create 1040 --firewall-policy="$POLICY" --global-firewall-policy --direction=INGRESS --action=deny --src-ip-ranges=10.10.200.0/24 --dest-ip-ranges=10.0.0.0/8 --layer4-configs=all '--description=Guests stay out'
run compute network-firewall-policies rules create 1050 --firewall-policy="$POLICY" --global-firewall-policy --direction=EGRESS --action=deny --src-ip-ranges=10.10.200.0/24 --dest-ip-ranges=10.0.0.0/8 --layer4-configs=all '--description=Guests stay out'
run compute network-firewall-policies rules create 1060 --firewall-policy="$POLICY" --global-firewall-policy --direction=INGRESS --action=allow --src-ip-ranges=0.0.0.0/0 --dest-ip-ranges=10.20.0.10/31 --layer4-configs=tcp:443,tcp:8443 --enable-logging '--description=Inbound web'
run compute network-firewall-policies rules create 1070 --firewall-policy="$POLICY" --global-firewall-policy --direction=EGRESS --action=allow --src-ip-ranges=0.0.0.0/0 --dest-ip-ranges=10.20.0.10/31 --layer4-configs=tcp:443,tcp:8443 --enable-logging '--description=Inbound web'
run compute network-firewall-policies rules create 1080 --firewall-policy="$POLICY" --global-firewall-policy --direction=INGRESS --action=allow --src-ip-ranges=10.20.0.10/31 --dest-ip-ranges=10.20.1.0/24 --layer4-configs=tcp:8443 '--description=Web to app'
run compute network-firewall-policies rules create 1090 --firewall-policy="$POLICY" --global-firewall-policy --direction=EGRESS --action=allow --src-ip-ranges=10.20.0.10/31 --dest-ip-ranges=10.20.1.0/24 --layer4-configs=tcp:8443 '--description=Web to app'
run compute network-firewall-policies rules create 1100 --firewall-policy="$POLICY" --global-firewall-policy --direction=INGRESS --action=allow --src-ip-ranges=10.10.5.10/31,10.10.5.12/30,10.10.5.16/30,10.10.5.20/32 --dest-ip-ranges=10.20.0.10/31,10.20.1.0/24 --layer4-configs=tcp:22 '--description=Admins SSH'
run compute network-firewall-policies rules create 1110 --firewall-policy="$POLICY" --global-firewall-policy --direction=EGRESS --action=allow --src-ip-ranges=10.10.5.10/31,10.10.5.12/30,10.10.5.16/30,10.10.5.20/32 --dest-ip-ranges=10.20.0.10/31,10.20.1.0/24 --layer4-configs=tcp:22 '--description=Admins SSH'
run compute network-firewall-policies rules create 1120 --firewall-policy="$POLICY" --global-firewall-policy --direction=INGRESS --action=deny --src-ip-ranges=0.0.0.0/5,8.0.0.0/7,10.0.0.0/13,10.8.0.0/15,10.10.0.0/22,10.10.4.0/24,10.10.5.0/29,10.10.5.8/31,10.10.5.21/32,10.10.5.22/31,10.10.5.24/29,10.10.5.32/27,10.10.5.64/26,10.10.5.128/25,10.10.6.0/23,10.10.8.0/21,10.10.16.0/20,10.10.32.0/19,10.10.64.0/18,10.10.128.0/17,10.11.0.0/16,10.12.0.0/14,10.16.0.0/12,10.32.0.0/11,10.64.0.0/10,10.128.0.0/9,11.0.0.0/8,12.0.0.0/6,16.0.0.0/4,32.0.0.0/3,64.0.0.0/2,128.0.0.0/1 --dest-ip-ranges=10.20.0.10/31,10.20.1.0/24 --layer4-configs=tcp:22 '--description=Others no SSH'
run compute network-firewall-policies rules create 1130 --firewall-policy="$POLICY" --global-firewall-policy --direction=EGRESS --action=deny --src-ip-ranges=0.0.0.0/5,8.0.0.0/7,10.0.0.0/13,10.8.0.0/15,10.10.0.0/22,10.10.4.0/24,10.10.5.0/29,10.10.5.8/31,10.10.5.21/32,10.10.5.22/31,10.10.5.24/29,10.10.5.32/27,10.10.5.64/26,10.10.5.128/25,10.10.6.0/23,10.10.8.0/21,10.10.16.0/20,10.10.32.0/19,10.10.64.0/18,10.10.128.0/17,10.11.0.0/16,10.12.0.0/14,10.16.0.0/12,10.32.0.0/11,10.64.0.0/10,10.128.0.0/9,11.0.0.0/8,12.0.0.0/6,16.0.0.0/4,32.0.0.0/3,64.0.0.0/2,128.0.0.0/1 --dest-ip-ranges=10.20.0.10/31,10.20.1.0/24 --layer4-configs=tcp:22 '--description=Others no SSH'
run compute network-firewall-policies rules create 1140 --firewall-policy="$POLICY" --global-firewall-policy --direction=INGRESS --action=allow --src-ip-ranges=10.10.7.15/32 --dest-ip-ranges=10.30.1.0/24 --layer4-configs=tcp:502 '--description=Engineering to PLCs'
run compute network-firewall-policies rules create 1150 --firewall-policy="$POLICY" --global-firewall-policy --direction=EGRESS --action=allow --src-ip-ranges=10.10.7.15/32 --dest-ip-ranges=10.30.1.0/24 --layer4-configs=tcp:502 '--description=Engineering to PLCs'
run compute network-firewall-policies rules create 1160 --firewall-policy="$POLICY" --global-firewall-policy --direction=INGRESS --action=allow --src-ip-ranges=10.10.0.0/16 --dest-ip-ranges=198.51.100.40/32 --layer4-configs=tcp:21 '--description=FTP to partner'
run compute network-firewall-policies rules create 1170 --firewall-policy="$POLICY" --global-firewall-policy --direction=EGRESS --action=allow --src-ip-ranges=10.10.0.0/16 --dest-ip-ranges=198.51.100.40/32 --layer4-configs=tcp:21 '--description=FTP to partner'
run compute network-firewall-policies rules create 1180 --firewall-policy="$POLICY" --global-firewall-policy --direction=INGRESS --action=allow --src-ip-ranges=::/0 --dest-ip-ranges=::/0 --layer4-configs=58 '--description=Ping over IPv6'
run compute network-firewall-policies rules create 1190 --firewall-policy="$POLICY" --global-firewall-policy --direction=EGRESS --action=allow --src-ip-ranges=::/0 --dest-ip-ranges=::/0 --layer4-configs=58 '--description=Ping over IPv6'
run compute network-firewall-policies rules create 1200 --firewall-policy="$POLICY" --global-firewall-policy --direction=INGRESS --action=allow --src-ip-ranges=10.10.0.0/16 --dest-ip-ranges=10.20.2.0/24 --layer4-configs=tcp:3306 --disabled '--description=Old rule'
run compute network-firewall-policies rules create 1210 --firewall-policy="$POLICY" --global-firewall-policy --direction=EGRESS --action=allow --src-ip-ranges=10.10.0.0/16 --dest-ip-ranges=10.20.2.0/24 --layer4-configs=tcp:3306 --disabled '--description=Old rule'
run compute network-firewall-policies rules create 1220 --firewall-policy="$POLICY" --global-firewall-policy --direction=INGRESS --action=deny --src-ip-ranges=0.0.0.0/0 --dest-ip-ranges=0.0.0.0/0 --layer4-configs=all --description=fwshift-default-deny
run compute network-firewall-policies rules create 1230 --firewall-policy="$POLICY" --global-firewall-policy --direction=EGRESS --action=deny --src-ip-ranges=0.0.0.0/0 --dest-ip-ranges=0.0.0.0/0 --layer4-configs=all --description=fwshift-default-deny
run compute network-firewall-policies rules create 1240 --firewall-policy="$POLICY" --global-firewall-policy --direction=INGRESS --action=deny --src-ip-ranges=::/0 --dest-ip-ranges=::/0 --layer4-configs=all --description=fwshift-default-deny
run compute network-firewall-policies rules create 1250 --firewall-policy="$POLICY" --global-firewall-policy --direction=EGRESS --action=deny --src-ip-ranges=::/0 --dest-ip-ranges=::/0 --layer4-configs=all --description=fwshift-default-deny

# Not written:
#   Block quarantined: references 'Quarantine': dynamic address group, members are not known statically; the source 'Quarantine' holds members only its platform knows; a rule of Google Cloud names addresses
#   LAN block the rest: not converted: follows a conditional jump to the application rules (rule 'LAN to the application rules'), which cannot be expressed
#   App to DB: not converted: direction IN only: NSX checks the other end of the connection against the rules below it, which one rule cannot say
#   TLS out: not converted: context profile SSL (layer 7: applications, domain names), which the model has no place for

echo 'Done. Associate the policy with the network when you are ready; until then nothing changes.' >&2
